import json

# Load the 1962 bulletin
with open('/app/resources/treasury_bulletin_1962_01.json', 'r') as f:
    data_1962 = json.load(f)

# Load the 1963 bulletin  
with open('/app/resources/treasury_bulletin_1963_01.json', 'r') as f:
    data_1963 = json.load(f)

# Find money in circulation data
def find_circulation_data(data):
    for item in data:
        if 'End of fiscal year or month' in item and 'Total money in circulation' in item:
            return item
    return None

# Check the table structure
print('Checking 1962 data structure...')
for key in list(data_1962.keys())[:5]:
    print(f'Key: {key}')

# Search for 'Treasury notes of 1890' in the data
def search_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if '1890' in str(k) or 'Treasury notes' in str(k):
                print(f'Found at {path}.{k}: {v}')
            search_keys(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_keys(item, f'{path}[{i}]')

search_keys(data_1962)
print('---')
search_keys(data_1963)
"
